"""Small dependency-free demo dashboard; it renders API JSON and contains no generated medical text."""
HTML = '''<!doctype html><html><head><title>GlucoPilot POC</title><style>body{font:16px system-ui;margin:2rem;background:#101827;color:#e5e7eb}button{padding:.7rem}pre{background:#172033;padding:1rem;overflow:auto}.badge{color:#fbbf24}</style></head><body><h1>GlucoPilot <span class="badge">POC — not clinical advice</span></h1><p>Run structured scenarios through the API. This dashboard displays returned simulation/forecast JSON only.</p><button onclick="run()">Load demo forecast</button><pre id="out">Ready.</pre><script>async function run(){const p=await fetch('/openapi.json').then(x=>x.json());document.querySelector('#out').textContent=JSON.stringify({available_paths:Object.keys(p.paths),warning:'Use /forecast, /permission, /plan-day, or /lifestyle-change with structured JSON.'},null,2)}</script></body></html>'''
